/*
 Jobtimize2 - schema and data export from the live local database
 Exported 2026-10-13. This is NOT JobtimizeDB and NOT Database_V2.sql.
 Target: SQL Server 2022 (or compatible newer version).
 Includes tables, constraints, indexes, triggers, sequence, diagram helpers,
 and current data (3 roles and 1 SSMS diagram; other tables are empty).
 Does not export server logins, passwords, or machine-specific file paths.

 Run once against a NEW/EMPTY Jobtimize2 database in SSMS, or use:
 sqlcmd -S localhost -E -C -b -f 65001 -i database/Jobtimize2.sql
 Existing objects are not dropped or overwritten. This is an initial schema,
 not an incremental migration. Do not run over an existing populated database.
 Changing the application DB_NAME alone is insufficient: current application
 queries target the different JobtimizeDB schema and need adaptation first.
*/
USE [master]
GO
IF DB_ID(N'Jobtimize2') IS NULL
    CREATE DATABASE [Jobtimize2]
GO
USE [Jobtimize2]
GO

